import React, { useState } from 'react'
import Navbar from '../component/Navbar'
import Footer from '../component/Footer'
import { Link, useNavigate } from 'react-router-dom';


const Registration = () => {
    const navigate = useNavigate();

    const [firstname,setFirstname]=useState("");
    const [lastname,setLastname]=useState("");
    const [email,setEmail]=useState("");
    const [password,setPassword]=useState("");

    const regcode = async (e)=>{
        e.preventDefault();
        const user={firstname,lastname,email,password};
        const response=await fetch('http://localhost:8000/',{
            method:'POST',
            headers:{
                "Content-Type":"application/json",
            },
            body:JSON.stringify(user)
        });
        const result = await response.json();
        if(result.msg==="Success"){
            alert("Registration Success");
            setFirstname("");
            setLastname("");
            setEmail("");
            setPassword("");
            navigate('/login');
        }
        else{
            alert("Registration Failed")
        }
    }

  return (
    <>
    <Navbar/>

    <div className='row text-login'>
        <div className='col-md-5 mx-auto p-5 shadow-lg my-5 rounded-5 border border-5'>
            <form onSubmit={regcode}>
                <h4><span className='text-danger text-decoration-underline '>Registration</span> Form</h4>
                Enter Your First Name : 
                <input className='form-control' value={firstname} onChange={(e)=>{ setFirstname(e.target.value)} } type="text" name="firstName" placeholder='Enter Your First Name'/>
                <br/>
                
                Enter Your Last Name :
                <input className='form-control' value={lastname}  onChange={(e)=>{setLastname(e.target.value)}} type="text" name="lastName" placeholder='Enter Your Last Name'/>
                <br/>
                Enter Your Email :
                <input className='form-control' value={email} onChange={(e)=>setEmail(e.target.value)} type="email" name="email" placeholder='Enter Your Email'/>
                <br/>
                Enter Your Password :
                <input className='form-control' value={password} onChange={(e)=>setPassword(e.target.value)} type="number" name="password" placeholder='Enter Your Passwoord'/>
                <br/>
                <button className='mb-3 form-control btn btn-primary' type="submit">Submit</button>

                <Link to={'/login'}>Already Have An Account || Login Here</Link>
            </form>
        </div>
    </div>
    <Footer/>
    </>
  )
}

export default Registration
